"""Insert B/C outputs into the new manuscript; every numerical cell is generated."""
import csv,json
from pathlib import Path
from v3_revision import ROOT,RESULT,para,sub,eq,table,readcsv

def augment(c,base):
    p=RESULT/'inference'
    if not (p/'B4-complete.json').exists():return
    dm=readcsv('results/revision-20261023/inference/dm.csv');cov=readcsv('results/revision-20261023/inference/coverage.csv');holm=readcsv('results/revision-20261023/inference/holm.csv');mu=readcsv('results/revision-20261023/inference/murphy-summary.csv')
    from v3_inference_presentation import family_readback
    family=family_readback(holm);adjusted=family['by_id']
    f=lambda x: 'NA' if x in (None,'') else format(float(x),'.3g')
    dmids=['fx_hourly-h6-QR2880-minus-rolling_F720','fx_hourly-h6-QR2880-minus-frozen_F2880','fx_hourly-h24-QR2880-minus-rolling_S720','nyfed_weekly-h6-QR260-minus-frozen_F260']
    names=['FX H6 primary','FX H6 matched','FX H24 legacy','Treasury H6 primary']
    chosen=[next(r for r in dm if r['contrast_id']==k) for k in dmids]
    c['sections'][4]['blocks'].extend([
      sub('Post-result inference'),
      para('After exact trace reproduction, we compare paired loss differences using Diebold–Mariano (1995) statistics with Bartlett Newey–West (1987) covariance. The fixed bandwidth is L=max{H,⌊4(n/100)<super>2/9</super>⌋}; doubled bandwidth supplies a sensitivity check. Harvey, Leybourne and Newbold (1997) supply the reported small-sample multiplier, here used as an approximation for pinball loss. Fixed finite estimation windows motivate the unconditional predictive-ability interpretation of Giacomini and White (2006), under mixing, adequate high-order moments and positive long-run variance. Shared training can extend dependence beyond the target horizon. These are working assumptions for this post-result analysis.'),
      eq('DM= d̄ / √(Ω̂/n); &nbsp; Ω̂=γ̂<sub>0</sub>+2∑<sub>j=1</sub><super>L</super>(1−j/(L+1))γ̂<sub>j</sub>; &nbsp; DM<sub>HLN</sub>=DM √[(n+1−2H+H(H−1)/n)/n].',r'DM=\frac{\bar d}{\sqrt{\widehat\Omega/n}},\quad\widehat\Omega=\widehat\gamma_0+2\sum_{j=1}^L(1-j/(L+1))\widehat\gamma_j,\quad DM_{HLN}=DM\sqrt{\frac{n+1-2H+H(H-1)/n}{n}}.'),
      para('Kupiec (1995) proportion-of-failures and Christoffersen (1998) independence/conditional-coverage diagnostics use the original first-origin-plus-j(H+1) grid. Conditional coverage here adds full-sample-grid POF to the transition-independence LR. A DQ-type full-sample HAC Wald adaptation of Engle and Manganelli (2004) uses the intercept, issue-known capacity and matured hit lags H+1 through H+4. Singular covariance or an unidentified transition row yields NA. The fixed 72-member common-history family receives Holm (1979) adjustment; exact identical losses use conservative p=1 solely for multiplicity bookkeeping. Appendix H and the output CSVs retain all statistics and statuses.')])
    t5=table('Table 5. Post-result / exploratory paired predictive-accuracy tests. Negative t favors QR; normal DM and Student-reference HLN p values are two sided. Holm p uses the fixed 72 common-history family; original cross-window FX comparisons are outside it. Original primaries and legacy remain fixed.', ['Comparison','L','DM t','DM p','HLN t','HLN p','Holm p'],[[name,r['bandwidth'],f(r['dm_t']),f(r['dm_p']),f(r['hln_t']),f(r['hln_p']),f(adjusted[r['contrast_id']]['holm_p']) if r['contrast_id'] in adjusted else 'Outside family'] for name,r in zip(names,chosen)])
    c['sections'][7]['blocks'].extend([sub('Post-result predictive accuracy and calibration'),t5])
    labels=[('fx_hourly',6,2880,'QR','FX QR H6'),('fx_hourly',6,720,'rolling_F','FX rolling F H6'),('fx_hourly',6,2880,'frozen_F','FX matched F H6'),('fx_hourly',24,2880,'QR','FX QR H24'),('fx_hourly',24,720,'rolling_S','FX legacy S H24'),('nyfed_weekly',6,260,'QR','Treasury QR H6'),('nyfed_weekly',6,260,'frozen_F','Treasury F H6')]
    cover=[]
    for s,h,w,m,label in labels:
        r=next(x for x in cov if (x['source'],int(x['horizon']),int(x['window']),x['method'])==(s,h,w,m));cover.append((label,r))
    t6=table('Table 6. Post-result / exploratory coverage diagnostics. k/n counts strict breaches on the fixed H+1 grid; POF/independence/CC are chi-square-reference p values. DQ is the overlap-aware full-sample HAC adaptation. Boundary and small-sample qualifications apply.', ['Report','k/n','POF p','Ind p','CC p','DQ p'],[[name,r['hits']+'/'+r['n'],f(r['pof_p']),f(r['ind_p']),f(r['cc_p']),f(r['dq_p'])] for name,r in cover])
    c['sections'][7]['blocks'].append(t6)
    rejects=sum(float(r['holm_p'])<.05 for r in holm)
    treasury=chosen[-1];fxlegacy=chosen[2]
    legacy_original=next(r for r in readcsv('results/revision-20261022/paired-comparisons.csv') if r['contrast_id']==fxlegacy['contrast_id'])
    legacy_gain=format(-float(legacy_original['relative_mean_loss_difference_percent']),'.2f')
    treasury_holm=adjusted[treasury['contrast_id']]['holm_p'];fx_holm=adjusted[chosen[1]['contrast_id']]['holm_p']
    c['sections'][7]['blocks'].append(para('The original FX H6 primary and matched-history comparison have negative DM statistics, while the Treasury primary has a positive statistic (Table 5). The FX H24 legacy has DM p='+f(fxlegacy['dm_p'])+' and HLN p='+f(fxlegacy['hln_p'])+', so its '+legacy_gain+'% descriptive improvement is not statistically significant at the 5% working-reference level. At the declared bandwidth, '+str(family['base_below_05'])+' of '+str(family['family_size'])+' Holm-adjusted working-reference p values fall below 5%, compared with '+str(family['double_below_05'])+' at doubled bandwidth. The declared-bandwidth count includes '+str(family['base_direction_counts']['favorable'])+' favorable and '+str(family['base_direction_counts']['adverse'])+' adverse mean differences for the conditional method. The matched FX H6 comparison has Holm p='+f(fx_holm)+'; the Treasury primary has Holm p='+f(treasury_holm)+' and does not meet that family-adjusted threshold. Its descriptive loss deterioration remains an adverse finding. On the Treasury primary grid, '+cover[-2][1]['hits']+'/'+cover[-2][1]['n']+' strict breaches yield POF p='+f(cover[-2][1]['pof_p'])+' and CC p='+f(cover[-2][1]['cc_p'])+'. These coverage diagnostics assess different nulls from paired equal predictive loss.'))

    # Main Murphy discussion, each full primary retained rather than picking a panel.
    c['sections'][7]['blocks'].extend([para('Figure 4 fixes τ=0.95 and varies the elementary-score threshold θ (Ehm et al., 2016). Both primary diagrams cross: QR has favorable and unfavorable threshold regions. Consequently neither report empirically dominates the other over the entire class of consistent 0.95-quantile scores. The check evaluates every unique forecast/outcome breakpoint privately; the displayed 201-point grid is an aggregate visualization. This differs from the archived preference frontier, which holds reports fixed and changes shortfall/excess weights. The calibration-and-sharpness perspective of Gneiting, Balabdaoui and Raftery (2007) motivates separate assessment of forecast concentration and calibration; the scalar capacity report addresses its stated functional.'),{'type':'figure','index':3},{'type':'figure','index':4}])
    for i,(source,label) in enumerate([('fx_hourly','FX'),('nyfed_weekly','Treasury')]):
        c['figures'].append(dict(path='figures/murphy-'+source+'.pdf',caption='Figure 4'+('a' if i==0 else 'b')+'. '+label+' original primary elementary quantile scores at fixed τ=0.95. Lower is better. The full-breakpoint check finds crossing; the display grid alone is not used to establish that finding.'))
    facts=json.loads((RESULT/'treasury-feature-audit.json').read_text())
    c['sections'][8]['blocks'].insert(0,sub('Feature transport and the Treasury failure'))
    varying_upper_bound=facts['predictors']-len(facts['constant_columns_zero_based'])
    c['sections'][8]['blocks'].insert(1,para('The executed QR specifications perform poorly on the weekly Treasury task. Their '+str(facts['lagged_level_coordinates'])+' level coordinates span the current observation through '+str(facts['max_lag_weeks'])+' weeks of history. The two hour coordinates, two weekday coordinates and gap indicator are exactly constant on this weekly source. Training-only centering makes those five columns exactly zero, so they provide no predictive variation and are not a demonstrated mechanism of overfitting. The original nominal design has '+str(facts['predictors'])+' predictors plus an intercept, or '+str(facts['coefficients_with_intercept'])+' coefficients, with at most '+str(varying_upper_bound)+' varying columns and '+str(varying_upper_bound+1)+' potentially predictive coefficients before other collinearity, against W='+str(facts['small_window'])+' overlapping training labels in the shorter history. All four Treasury penalty selections are menu endpoints. Its '+str(facts['validation_origins'])+' validation origins contain at most '+str((facts['validation_origins']-1)//(24+1)+1)+' disjoint H24 label paths, a path count rather than an effective-sample-size estimate. Correlated lag levels, overlapping labels, restricted tuning, target dynamics and reporting composition remain competing explanations. Neither the parsimonious sensitivity nor the aggregate panel separates those mechanisms.'))
    summary=RESULT/'parsimonious/summary.csv'
    if summary.exists():
        new=list(csv.DictReader(summary.open()));c2rows=[]
        for r in new:
            c2rows.append(['Treasury' if r['source']=='nyfed_weekly' else 'FX',r['horizon'],r['window'],f(r['selected_penalty']),f(r.get('percent_vs_QR')),f(r.get('percent_vs_frozen_F')),r.get('strict_breach_count','NA'),r['status']])
        c['sections'][8]['blocks'].insert(2,table('Table 7. Post-result / exploratory parsimonious QR. Four predictors plus intercept, expanded validation penalty menu, original split/refit schedule. Percent changes compare loss against the original QR and matched F. Every original primary remains unchanged.', ['Source','H','W','λ','Δ QR %','Δ F %','Breaches','Status'],c2rows))
        good=sum(r['status']=='COMPLETE' and float(r['percent_vs_QR'])<0 for r in new);fbetter=sum(r['status']=='COMPLETE' and float(r['percent_vs_frozen_F'])<0 for r in new)
        tr=next(r for r in new if (r['source'],r['horizon'],r['window'])==('nyfed_weekly','6','260'))
        c['sections'][8]['blocks'].insert(3,para('The four-predictor sensitivity uses B, signed N and short/long increment RMS, with validation penalties {0.001,0.01,0.1,1,10}. It lowers loss against the original QR in '+str(good)+' of '+str(len(new))+' cells and against matched F in '+str(fbetter)+' cells. In the Treasury primary cell its loss change is '+f(tr['percent_vs_QR'])+'% relative to the original QR and '+f(tr['percent_vs_frozen_F'])+'% relative to F. All adverse cells remain in Table 7. The exercise changes features and the penalty menu jointly, so it measures a parsimonious specification sensitivity rather than identifying a feature-only cause or rehabilitating the original primary.'))
    # Archive every full statistic without displacing the main narrative.
    c['sections'].append(dict(title='Appendix H. Complete post-result inference and specification outputs',blocks=[
      para('The complete machine-readable DM, HLN, doubled-bandwidth,72-family Holm, sparse-grid coverage and full-sample DQ-type results are retained in results/revision-20261023/inference/. Each NA retains an explicit reason. The accompanying scripts and known-answer tests are supplied together. The exact replicated six-table audit and source identities are in recovery/. Raw FX data and origin-level traces remain private.'),
      para('The HAC covariance uses centered moment products with denominator n. DQ instruments are the intercept, four matured hit lags and standardized issue-known capacity; its chi-square reference has six degrees of freedom when full rank. The covariance must be finite, full rank and positive definite. The doubled bandwidth remains much shorter than the longest training history, so this limited check does not establish adequate long-run covariance calibration. Sparse grid tests remove overlapping target windows but retain shared training dependence. Treasury grid sizes of40 or12 are particularly weak for asymptotic reference calibration. The equality-based POF, CC and DQ diagnostics require exact5% moments; a quantile with atoms can validly be conservative, so rejection by low hit frequency differs from undercoverage. Missing transition-state rows render independence and CC unidentified. POF uses all grid hits, whereas the independence statistic uses transitions conditional on the first hit. The retained CC statistic is their sum, combining these two initialization conventions; it is not the finite-sample likelihood-ratio expression obtained by conditioning both components on the first observation as in Christoffersen (1998, p. 847). Its chi-square p value remains an asymptotic working reference subject to the dependence, boundary and small-sample limitations stated here. HLN was derived for mean-squared-error comparisons; pinball p values are approximate. Holm familywise control requires valid component p values: the adjustment does not validate the working DM references or remove post-inspection selection. All analyses are post-result and reuse inspected samples.'),
      para('The DQ-type null is E[Z<sub>t</sub>(I<sub>t</sub>−.05)]=0 for the six raw instruments: the intercept, four mature hit lags and issued capacity. The implementation centers/scales capacity across diagnostic rows for numerical conditioning. With the intercept and a finite positive capacity standard deviation, this common invertible column transformation leaves the Wald statistic unchanged in exact arithmetic. Its sample constants are not forecast inputs or claimed available at issue. Rejection concerns these moments; nonrejection leaves other conditional departures untested. The original out-of-sample CAViaR theorem assumes growing estimation and evaluation samples with their evaluation-to-estimation ratio tending to zero. The fixed-window, overlapping-target HAC calculation here is an adaptation, not a direct application of that theorem.'),
      table('Table H1. Murphy full-breakpoint audit for both original primaries. The extrema of left-minus-right elementary scores span zero in both cases. Integral agreement is an arithmetic identity check.', ['Source','Breakpoints','Minimum Δ','Maximum Δ','Sample ranking'],[[('FX' if r['source']=='fx_hourly' else 'Treasury'),r['breakpoint_count'],f(r['min_elementary_difference']),f(r['max_elementary_difference']),r['ranking']] for r in mu])]))
    all_rows=[]
    for r in holm:
        significant=float(r['holm_p'])<.05
        sign='Favorable' if float(r['mean_difference'])<0 else ('Adverse' if float(r['mean_difference'])>0 else 'Identical')
        status=('Below .05' if significant else 'At least .05')+'; '+sign+'; '+r['status']
        all_rows.append(['FX' if r['source']=='fx_hourly' else 'Treasury',r['horizon'],r['left_window'],r['left_method'].replace('SCALED_KNN','Scaled KNN'),r['right_method'].removeprefix('frozen_'),f(r['dm_t']),f(r['dm_p']),f(r['holm_p']),status])
    assert len(all_rows)==72 and len({r['contrast_id'] for r in holm})==72
    c['sections'][-1]['blocks'].append(table('Table H2. Complete fixed 72-member common-history Holm family, including nonsignificant and identical-loss rows. Comparators F/S/K are frozen with the displayed common W. Negative t favors the conditional method. The .05 decision is based on unrounded normal-reference DM p values and Holm adjustment; it is an exploratory working-reference decision conditional on valid component tests. Identical losses retain their NA t/status and bookkeeping p=1.', ['Source','H','W','Conditional','Ref','DM t','DM p','Holm p','Decision / direction / status'],all_rows))
    newrefs=[
      ('dm1995','Diebold, F.X. and R.S. Mariano (1995). Comparing Predictive Accuracy. <i>Journal of Business &amp; Economic Statistics</i> 13(3), 253–263.','10.1080/07350015.1995.10524599'),
      ('hln1997','Harvey, D., S. Leybourne and P. Newbold (1997). Testing the equality of prediction mean squared errors. <i>International Journal of Forecasting</i> 13(2), 281–291.','10.1016/S0169-2070(96)00719-4'),
      ('gw2006','Giacomini, R. and H. White (2006). Tests of Conditional Predictive Ability. <i>Econometrica</i> 74(6), 1545–1578.','10.1111/j.1468-0262.2006.00718.x'),
      ('kupiec1995','Kupiec, P.H. (1995). Techniques for Verifying the Accuracy of Risk Measurement Models. <i>Journal of Derivatives</i> 3(2), 73–84.','10.3905/jod.1995.407942'),
      ('christ1998','Christoffersen, P.F. (1998). Evaluating Interval Forecasts. <i>International Economic Review</i> 39(4), 841–862.','10.2307/2527341'),
      ('ehm2016','Ehm, W., T. Gneiting, A. Jordan and F. Krüger (2016). Of quantiles and expectiles: consistent scoring functions, Choquet representations and forecast rankings. <i>Journal of the Royal Statistical Society, Series B</i> 78(3), 505–562.','10.1111/rssb.12154'),
      ('gneiting2007','Gneiting, T., F. Balabdaoui and A.E. Raftery (2007). Probabilistic forecasts, calibration and sharpness. <i>Journal of the Royal Statistical Society, Series B</i> 69(2), 243–268.','10.1111/j.1467-9868.2007.00587.x')]
    for rid,text,doi in newrefs:c['references'].append(dict(id=rid,html=text+" <a href='https://doi.org/"+doi+"'>DOI</a>."))
    c['references'].extend([dict(id='nw1987',html="Newey, W.K. and K.D. West (1987). A Simple, Positive Semi-Definite, Heteroskedasticity and Autocorrelation Consistent Covariance Matrix. <i>Econometrica</i> 55(3), 703–708. <a href='https://www.jstor.org/stable/1913610'>Publisher record</a>."),dict(id='holm1979',html="Holm, S. (1979). A Simple Sequentially Rejective Multiple Test Procedure. <i>Scandinavian Journal of Statistics</i> 6(2), 65–70. <a href='https://www.jstor.org/stable/4615733'>Publisher record</a>.")])
    # The pre-existing summary is Table5; inferential and C2 tables follow it.
    for s in c['sections']:
        for b in s['blocks']:
            for key in ('caption','html'):
                if key in b:
                    b[key]=b[key].replace('Table 7','Table 8').replace('Table 6','Table 7')
                    if 'paired predictive-accuracy' in b[key] or ('Table 5' in b[key] and b['type']=='p'):b[key]=b[key].replace('Table 5','Table 6')
